BEGIN;
SET LOCAL statement_timeout='10s';
DO $test$
DECLARE r record; n integer;
BEGIN
IF current_user <> 'postgres' THEN RAISE EXCEPTION 'AUTHORIZED_ADMIN_REQUIRED'; END IF;
IF EXISTS(SELECT 1 FROM public.stellar_orchestrator_workflows_staging) OR EXISTS(SELECT 1 FROM public.stellar_orchestrator_events_staging) OR EXISTS(SELECT 1 FROM public.stellar_dispatch_receipts_staging) OR EXISTS(SELECT 1 FROM public.stellar_dispatch_effects_staging) THEN RAISE EXCEPTION 'BASELINE_CHANGED';END IF;
IF (SELECT md5(coalesce(string_agg(to_jsonb(c)::text,'' ORDER BY id),'')) FROM public.stellar_support_cases c)<>'ddeb4729999cd8a90965ab2197b4355c' OR (SELECT md5(coalesce(string_agg(to_jsonb(c)::text,'' ORDER BY id),'')) FROM public.ai4cc_contacts c)<>'a67f355fc8bc1a3e258ab772b308c485' THEN RAISE EXCEPTION 'BASELINE_CHANGED';END IF;
EXECUTE 'SET LOCAL ROLE service_role';
SELECT * INTO STRICT r FROM public.stellar_create_phone_support_test_intake('5885a020-d363-4c27-910a-c035eda132f5'::uuid,'phone-staging:CAb27e2890a06a4e7aaf15900052661cd4','Fictional staging customer','gateway-b27e2890-a06a-4e7a-af15-900052661cd4@example.invalid','','Synthetic staging router','2026-10-01'::date,'Fictional staging gateway acceptance; no real customer or notification.','gateway-b27e2890-a06a-4e7a-af15-900052661cd4','No real business affected','NORMAL');
IF r.created_new IS DISTINCT FROM true OR r.case_id IS NULL OR r.customer_id IS NULL THEN RAISE EXCEPTION 'NEW_FIXTURE_REQUIRED';END IF;
EXECUTE 'RESET ROLE';
IF NOT EXISTS(SELECT 1 FROM public.stellar_support_cases c JOIN public.ai4cc_contacts k ON k.id=c.contact_id AND k.tenant_id=c.tenant_id WHERE c.id=r.case_id AND k.id=r.customer_id AND c.tenant_id='5885a020-d363-4c27-910a-c035eda132f5'::uuid AND c.test_only=true AND c.intake_session_id='phone-staging:CAb27e2890a06a4e7aaf15900052661cd4' AND k.email='gateway-b27e2890-a06a-4e7a-af15-900052661cd4@example.invalid' AND k.metadata->>'test_only'='true' AND k.metadata->>'notifications_disabled'='true') THEN RAISE EXCEPTION 'FIXTURE_METADATA_INVALID';END IF;
INSERT INTO public.stellar_orchestrator_workflows_staging(workflow_id,tenant_id,session_id,call_id,tool_call_id,workflow_type,state,case_id,version) VALUES('b27e2890-a06a-4e7a-af15-900052661cd4','5885a020-d363-4c27-910a-c035eda132f5','phone-staging:CA19a4575f189d4c22ab084dd5a58889d0','CA19a4575f189d4c22ab084dd5a58889d0','gateway:931adb90-1c80-4dc7-b01f-a6c1e4104a59','support_ticket_creation','COMPLETED',r.case_id,1);
GET DIAGNOSTICS n=ROW_COUNT;IF n<>1 THEN RAISE EXCEPTION 'WORKFLOW_COUNT_INVALID';END IF;
IF (SELECT count(*) FROM public.stellar_support_cases)<>21 OR (SELECT count(*) FROM public.ai4cc_contacts)<>14 OR EXISTS(SELECT 1 FROM public.stellar_support_cases WHERE intake_session_id='phone-staging:CA19a4575f189d4c22ab084dd5a58889d0') OR EXISTS(SELECT 1 FROM public.stellar_orchestrator_events_staging) OR EXISTS(SELECT 1 FROM public.stellar_dispatch_receipts_staging) OR EXISTS(SELECT 1 FROM public.stellar_dispatch_effects_staging) THEN RAISE EXCEPTION 'FIXTURE_COUNTS_INVALID';END IF;
IF (SELECT md5(coalesce(string_agg(to_jsonb(c)::text,'' ORDER BY id),'')) FROM public.stellar_support_cases c WHERE id<>r.case_id)<>'ddeb4729999cd8a90965ab2197b4355c' OR (SELECT md5(coalesce(string_agg(to_jsonb(c)::text,'' ORDER BY id),'')) FROM public.ai4cc_contacts c WHERE id<>r.customer_id)<>'a67f355fc8bc1a3e258ab772b308c485' THEN RAISE EXCEPTION 'ORIGINAL_ROWS_CHANGED';END IF;
END $test$;
COMMIT;
SELECT now() observed_at,w.*,c.contact_id,c.intake_session_id case_session,k.email,md5(to_jsonb(w)::text) workflow_hash,md5(to_jsonb(c)::text) case_hash,md5(to_jsonb(k)::text) contact_hash FROM public.stellar_orchestrator_workflows_staging w JOIN public.stellar_support_cases c ON c.id=w.case_id JOIN public.ai4cc_contacts k ON k.id=c.contact_id WHERE w.workflow_id='b27e2890-a06a-4e7a-af15-900052661cd4';

