IF (SELECT count(*) FROM public.stellar_orchestrator_workflows_staging WHERE case_id='9a82b21f-b772-4ad0-abae-2520bdefb4d2')<>1 OR (SELECT count(*) FROM public.stellar_support_cases WHERE contact_id='3ea6bc8a-d660-49c0-b349-186cf6d6ae1b')<>1 THEN RAISE EXCEPTION 'OTHER_REFERENCES';END IF;
