DELETE FROM public.ai4cc_contacts WHERE id='3ea6bc8a-d660-49c0-b349-186cf6d6ae1b' AND tenant_id='5885a020-d363-4c27-910a-c035eda132f5' AND email='gateway-b27e2890-a06a-4e7a-af15-900052661cd4@example.invalid' AND metadata->>'test_only'='true' AND metadata->>'notifications_disabled'='true';GET DIAGNOSTICS n=ROW_COUNT;IF n<>1 THEN RAISE EXCEPTION 'CONTACT_DELETE_COUNT';END IF;
IF (SELECT md5(coalesce(string_agg(to_jsonb(c)::text,'' ORDER BY id),'')) FROM public.stellar_support_cases c)<>'ddeb4729999cd8a90965ab2197b4355c' OR (SELECT md5(coalesce(string_agg(to_jsonb(c)::text,'' ORDER BY id),'')) FROM public.ai4cc_contacts c)<>'a67f355fc8bc1a3e258ab772b308c485' THEN RAISE EXCEPTION 'ORIGINAL_ROWS_CHANGED';END IF;
END $cleanup$;COMMIT;
SELECT now() cleanup_observed_at, 'EXACT_WORKFLOW_CASE_CONTACT_REMOVED' result;
